ALTER POLICY "editorial_history_read" ON "editorial_history" TO sep_runtime USING ("editorial_history"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "editorial_history"."event_id"=nullif(current_setting('sep.event_id',true),'')::uuid AND current_setting('sep.editorial_staff',true)='true' OR ("editorial_history"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "editorial_history"."event_id"=nullif(current_setting('sep.event_id',true),'')::uuid AND EXISTS(SELECT 1 FROM author_works w WHERE w.organization_id="editorial_history"."organization_id" AND w.event_id="editorial_history"."event_id" AND w.id="editorial_history"."work_id" AND w.owner_id=nullif(current_setting('sep.person_id',true),'')::uuid) AND "editorial_history"."action" IN ('permission_granted','permission_revoked')));